<file path="src/invoices.js">
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate } from './dates.js';

/**
 * Create a new invoice draft.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate date format and check if it's a real date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Get tier discount for this customer
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  // Process and validate each line
  const processedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: use line's value if provided, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: processedLines,
  });
}

/**
 * Calculate the total for a single line: qty times unitPrice.
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal, discount, VAT and total for an invoice. Subtotal is the sum of line totals.
 * Discount is the sum of line discounts. VAT is computed per line on the amount after discount, then rounded and summed.
 * Total = subtotal - discount + vat, clamped at 0.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }}
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineDiscount = lineTotal(line) * (line.discountPercent ?? 0) / 100;
    return sum + lineDiscount;
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const lineAmount = lineTotal(line);
    const lineDiscount = lineAmount * (line.discountPercent ?? 0) / 100;
    const amountAfterDiscount = lineAmount - lineDiscount;
    const lineVat = roundCents(amountAfterDiscount * (line.vatRate ?? 0) / 100);
    return sum + lineVat;
  }, 0);
  const total = Math.max(0, subtotal - discount + vat);
  return { subtotal, discount, vat, total };
}

/**
 * Add a line to an invoice draft, or increase qty if that SKU already exists.
 * @param {{ status: string, customerId: string, lines: Array<any> }, { sku: string, qty: number, discountPercent?: number }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get customer to apply tier discount if needed
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier] ?? 0;

  // Determine discountPercent: use provided value if given, otherwise use tier discount
  const finalDiscount = discountPercent !== undefined ? discountPercent : tierDiscount;
  if (typeof finalDiscount !== 'number' || finalDiscount < 0 || finalDiscount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Check if line already exists
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    // Line exists, increase qty
    const newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex ? { ...line, qty: line.qty + qty } : line
    );
    return ok({ ...invoice, lines: newLines });
  } else {
    // New line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscount,
    };
    return ok({ ...invoice, lines: [...invoice.lines, newLine] });
  }
}

/**
 * Remove a line from an invoice draft.
 * @param {{ status: string, lines: Array<{ sku: string }> }, string }
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if it's the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove the line
  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);
  return ok({ ...invoice, lines: newLines });
}

/**
 * Issue an invoice draft, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }, Array<string> }
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Return issued invoice
  return ok({ ...invoice, status: 'issued', number });
}
</file>

<file path="src/money.js">
import { ok, fail } from './result.js';

/**
 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
 * @param {number} x
 * @returns {number}
 */
export function roundCents(x) {
  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

/**
 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
 * @param {number} cents
 * @returns {string}
 */
export function formatEuros(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
}

/**
 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
 * @param {string} text
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function parseEuros(text) {
  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
  if (!m) return fail('AMOUNT_INVALID');
  const euros = Number(m[1].replace(/,/g, ''));
  const cents = Number((m[2] ?? '').padEnd(2, '0'));
  return ok(euros * 100 + cents);
}
</file>

<file path="src/numbering.js">
/**
 * Get the next free invoice number for a given issue date.
 * Format: INV-YYYY-NNNN where NNNN restarts at 0001 each year.
 * @param {Array<string>} existingNumbers - Invoice numbers already used, in any order
 * @param {string} issueDate - Date in YYYY-MM-DD format
 * @returns {string}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  const year = issueDate.substring(0, 4);

  // Filter numbers for this year
  const thisYearPattern = new RegExp(`^INV-${year}-\\d{4}$`);
  const thisYearNumbers = existingNumbers.filter((n) => thisYearPattern.test(n));

  // Extract counters and find max
  const counters = thisYearNumbers.map((n) => parseInt(n.substring(n.lastIndexOf('-') + 1), 10));
  const maxCounter = counters.length > 0 ? Math.max(...counters) : 0;

  // Return next counter
  const nextCounter = maxCounter + 1;
  return `INV-${year}-${String(nextCounter).padStart(4, '0')}`;
}
</file>

<file path="src/render.js">
import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { ok, fail } from './result.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text: number/DRAFT, customer, line items, VAT, total.
 * All amounts are formatted with formatEuros().
 * @param {{ customerId: string, number?: string, lines: Array<any> }}
 */
export function renderInvoiceText(invoice) {
  // Look up customer
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Build lines
  const lines = [];

  // Invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Customer name
  lines.push(customer.name);

  // Invoice lines
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    lines.push(`${line.qty} ${line.name} ${formatEuros(line.unitPrice)} ${formatEuros(total)}`);
  }

  // VAT and Total
  const totals = invoiceTotals(invoice);
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return ok(lines.join('\n'));
}
</file>

<file path="src/result.js">
/**
 * A successful result.
 * @template T
 * @param {T} value
 * @returns {{ ok: true, value: T }}
 */
export function ok(value) {
  return { ok: true, value };
}

/**
 * A failed result. `error` is an error code from ERRORS in src/errors.js.
 * @param {string} error
 * @param {unknown} [details]
 * @returns {{ ok: false, error: string, details?: unknown }}
 */
export function fail(error, details) {
  return details === undefined ? { ok: false, error } : { ok: false, error, details };
}
</file>

